		return errIndexOutOfBounds
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	v := s.cache[ident.root]
	v.epoch = ident.epoch
	if v.mask == nil {
		v.mask = make(blobIndexMask, maxBlobsPerBlock)
	}
	if !v.mask[ident.index] {
